L=[]
def add(t,u,g,d,e,ur,b,p,tags='',h='',pre=''):
 L.append(dict(id=len(L)+1,title=t,ur=u,group=g,definition=d,explanation=e,urdu=ur,code='#include <iostream>\n'+''.join('#include <'+x+'>\n' for x in h.split())+'\n'+(pre+'\n\n' if pre else '')+'int main() {\n'+'\n'.join('    '+x for x in b.split('\n'))+'\n}\n',practice=p,tags=tags,minutes=5+len(L)%4,source=('Lafore · Chapter '+g.split('.')[0]) if g[0].isdigit() else 'Additional roadmap · '+g))
add('Your first C++ program','آپ کا پہلا پروگرام','2. Foundations','A C++ program is a set of instructions compiled into an executable.','Execution starts in main(). The iostream header supplies input/output. std::cout writes to the console; a semicolon ends a statement. Returning 0 from main signals success.','پروگرام main() سے شروع ہوتا ہے۔ std::cout سکرین پر متن دکھاتا ہے۔ ہر بیان کے آخر میں سیمی کولن لگائیں۔ iostream ان پٹ اور آؤٹ پٹ کی سہولت دیتا ہے۔','std::cout << "Hello, learner!\\n";\nreturn 0;','Print your name and your learning goal on separate lines.','hello world main syntax directives comments program structure')
add('Thinking in objects','آبجیکٹ کی صورت میں سوچیں','1. The big picture','OOP groups state and behavior into objects.','Procedural programming organizes work around functions. A class describes a type; each object is an instance with its own state. Model entities only when that makes the problem clearer.','کلاس ایک خاکہ ہے اور آبجیکٹ اس کی مثال ہے۔ ہر طالب علم کا اپنا نام اور نمبر ہو سکتا ہے۔ فنکشن معلومات پر کام کرتا ہے۔','Student a{"Ayesha",90};\nstd::cout << a.name << ": " << a.score;','Create another student with a different score.','procedural OOP C versus C++ reusability polymorphism UML','string','struct Student { std::string name; int score; };')
add('Variables & data types','متغیر اور ڈیٹا ٹائپ','2. Foundations','A variable is a named object holding a value of a particular type.','Use int for whole numbers, double for fractions, char for one character and bool for true/false. Initialize before reading. const prevents reassignment.','int پورے عدد، double اعشاری عدد، char ایک حرف اور bool درست یا غلط کے لیے ہے۔ استعمال سے پہلے متغیر کو قدر دیں۔','int age{20};\ndouble score{92.5};\nconst char grade{\'A\'};\nstd::cout << age << " " << score << " " << grade;','Create a bool named passed and print it.','integer float char bool const initialization')
add('Input, output & formatting','ان پٹ اور آؤٹ پٹ','2. Foundations','Streams transfer formatted data into and out of a program.','cin >> reads a token; getline reads a line. Check extraction before using input. setw sets the next field width; fixed and setprecision control decimal display.','cin سے معلومات لیتے اور cout سے دکھاتے ہیں۔ غلط ان پٹ چیک کریں۔ getline پوری لائن پڑھتا ہے۔ setprecision اعشاری ہندسوں کی تعداد طے کرتا ہے۔','double price{};\nif (std::cin >> price) std::cout << std::fixed << std::setprecision(2) << price;\nelse std::cout << "Enter a number.";','Enter 12.345 in Program input. Change precision to 1.','cout cin setw getline iomanip','iomanip')
add('Operators & conversions','آپریٹر اور تبدیلی','2. Foundations','Operators calculate values; conversions change value representation.','Integer division discards a fractional part. Convert an operand to double for fractional division. static_cast makes numeric conversion explicit. Parentheses clarify precedence.','دو int کی تقسیم میں اعشاری حصہ ختم ہو جاتا ہے۔ اعشاری جواب کے لیے ایک عدد double بنائیں۔ قوسین حساب کی ترتیب واضح کرتی ہیں۔','int a{7}, b{2};\nstd::cout << a/b << "\\n" << static_cast<double>(a)/b;','Predict both results, then change a to 9.','arithmetic modulo type conversion casts precedence library functions')
add('Decisions: if & switch','شرط اور فیصلہ','3. Control flow','Conditionals choose which statements execute.','if tests a condition; else handles the alternative. switch selects an integral or enum case. break prevents accidental fall-through. == compares while = assigns.','if شرط درست ہونے پر چلتا ہے۔ else دوسری صورت سنبھالتا ہے۔ switch قدر کے مطابق راستہ چنتا ہے۔ == موازنہ اور = قدر دینے کے لیے ہے۔','int marks{75};\nif (marks >= 50) std::cout << "Passed\\n";\nelse std::cout << "Try again\\n";\nstd::cout << (marks >= 80 ? "Excellent" : "Keep learning");','Add a distinction condition for 90 or more.','if else switch ternary conditional relational logical && || !')
add('Loops: for, while & do','لوپ اور تکرار','3. Control flow','Loops repeat statements while a condition holds.','for suits counted traversal. while checks first; do-while executes at least once. break exits and continue skips the rest of an iteration. Ensure progress toward termination.','لوپ کام بار بار کرتا ہے۔ while پہلے شرط دیکھتا ہے۔ do-while کم از کم ایک بار چلتا ہے۔ شرط بدلنی چاہیے ورنہ لوپ ختم نہیں ہوگا۔','for (int i{1}; i <= 5; ++i) {\n    if (i == 3) continue;\n    std::cout << i << " ";\n}','Print even numbers from 2 through 20.','for while do break continue goto')
add('Structures & enumerations','سٹرکچر اور اینم','4. Structures','A struct groups related members; an enum names integral constants.','Access members with a dot. Structures can contain other structures. Traditional enum names enter the surrounding scope; enum class is the modern scoped alternative.','struct متعلقہ معلومات اکٹھی رکھتا ہے۔ رکن تک ڈاٹ سے پہنچتے ہیں۔ ایک سٹرکچر کے اندر دوسرا بھی ہو سکتا ہے۔ enum مخصوص قدروں کو نام دیتا ہے۔','Point p{3,4};\nstd::cout << p.x << ", " << p.y;','Add a z member for a 3D point.','nested structures enum card game','', 'struct Point { int x; int y; };')
add('Functions & return values','فنکشن اور نتیجہ','5. Functions','A function is a named operation with parameters and an optional result.','A declaration describes an interface; a definition supplies the body. Value parameters are independent copies. return sends a result to the caller. Keep one clear responsibility per function.','فنکشن ایک کام کو نام دیتا ہے۔ پیرامیٹر معلومات لیتا ہے اور return نتیجہ دیتا ہے۔ ویلیو سے پاس کرنے پر اصل متغیر نہیں بدلتا۔','std::cout << square(6);','Write a cube function and call it with 3.','declaration definition pass by value returning inline scope storage const arguments','', 'int square(int n) { return n*n; }')
add('References & default arguments','ریفرنس اور ڈیفالٹ آرگومنٹ','5. Functions','A reference is another name for an existing object.','T& can modify the original; const T& reads without copying. Default arguments supply omitted values and follow required parameters. Never return a reference to a destroyed local variable.','ریفرنس اصل متغیر کا دوسرا نام ہے۔ & سے اصل قدر بدل سکتی ہے۔ const ریفرنس تبدیلی روکتا ہے۔ ڈیفالٹ قدر تب آتی ہے جب آرگومنٹ نہ دیا جائے۔','int points{10};\naddPoints(points);\nstd::cout << points;','Call addPoints with 7 as the second argument.','pass by reference const default arguments','', 'void addPoints(int& n, int extra=5) { n+=extra; }')
add('Overloading & recursion','اوور لوڈنگ اور ریکرشن','5. Functions','Overloads share a name; recursion is a function calling itself.','Overloads need different parameter lists, not just return types. Recursion needs a base case and progress toward it. Deep recursive calls can exhaust stack space.','ایک نام کے فنکشن مختلف پیرامیٹر لے سکتے ہیں۔ ریکرشن میں فنکشن خود کو بلاتا ہے۔ رکنے کی شرط اور اس کی طرف پیش رفت ضروری ہے۔','std::cout << factorial(5);','Call factorial(0) and explain the base case.','overloaded function recursion','', 'int factorial(int n) { if(n<=1) return 1; return n*factorial(n-1); }')
add('Classes & encapsulation','کلاس اور انکیپسولیشن','6. Objects & classes','Classes define types with data, operations and access control.','private hides implementation; public provides an interface. Encapsulation protects valid states. A const member function promises not to modify ordinary data members through this.','کلاس ڈیٹا اور فنکشن اکٹھے کرتی ہے۔ private معلومات باہر سے محفوظ رکھتا ہے۔ public فنکشن کے ذریعے درست طریقے سے کام کیا جاتا ہے۔','Counter c;\nc.increment();\nc.increment();\nstd::cout << c.value();','Add reset() to set count to zero.','class object private public encapsulation const member','', 'class Counter {\n    int count{0};\npublic:\n    void increment() { ++count; }\n    int value() const { return count; }\n};')
add('Constructors & destructors','کنسٹرکٹر اور ڈسٹرکٹر','6. Objects & classes','Constructors initialize objects; destructors run at the end of their lifetime.','Member initializer lists initialize members directly. Constructors can be overloaded. Prefer standard owning members so cleanup is automatic rather than writing manual resource management.','کنسٹرکٹر آبجیکٹ بننے پر ابتدا کرتا ہے۔ ڈسٹرکٹر زندگی ختم ہونے پر چلتا ہے۔ ممبر انیشلائزر لسٹ سے ارکان کی ابتدائی قدر دیں۔','{ Greeting g{"Ali"}; }\nstd::cout << "Scope ended";','Create two objects and observe destruction order.','overloaded constructor copy constructor static class data destructor','string', 'class Greeting {\n    std::string name;\npublic:\n    explicit Greeting(std::string n): name(n) { std::cout << "Hello " << name << "\\n"; }\n    ~Greeting() { std::cout << "Goodbye " << name << "\\n"; }\n};')
add('Arrays & multidimensional data','ارے اور کئی جہتیں','7. Arrays & strings','Arrays store a fixed number of same-type elements.','Indices start at zero. Out-of-bounds access is undefined behavior. Two-dimensional arrays model tables. Use vector for growing sequences and array for modern fixed-size storage.','ارے ایک قسم کی کئی قدریں رکھتا ہے۔ پہلا انڈیکس صفر ہے۔ حد سے باہر رسائی غلط ہے۔ دو جہتی ارے جدول کی طرح ہوتا ہے۔','int marks[3]{70,80,90};\nfor (int x : marks) std::cout << x << " ";','Calculate the sum of all marks.','multidimensional array arrays of structures objects bounds')
add('Strings & text','سٹرنگ اور متن','7. Arrays & strings','std::string owns a character sequence and manages its storage.','C strings terminate with a null character and require careful buffer sizing. string supports concatenation and search. at() checks bounds, whereas operator[] generally does not.','std::string متن اور اس کی میموری سنبھالتا ہے۔ + سے متن جوڑیں اور size() سے لمبائی لیں۔ C سٹرنگ کے آخر میں null حرف ہوتا ہے۔','std::string name{"Ayesha"};\nstd::cout << "Hello, " + name << "\\n" << name.size();','Read a full name with getline and greet that person.','C strings cstring char array user-defined string','string')
add('Operator overloading','آپریٹر اوور لوڈنگ','8. Operator overloading','Overloading gives an existing operator behavior for a user-defined type.','Keep meanings intuitive. At least one operand must be a class or enum type. You cannot change precedence or operand count. explicit constructors prevent unwanted implicit conversions.','اپنی کلاس کے لیے + جیسے آپریٹر کا عمل طے کر سکتے ہیں۔ مطلب واضح رکھیں۔ آپریٹر کی ترجیح یا آرگومنٹ کی تعداد نہیں بدل سکتے۔','Length a{3}, b{4};\nstd::cout << (a+b).meters;','Add an equality operator.','unary binary [] conversion explicit mutable UML associations pitfalls','', 'struct Length { int meters; Length operator+(const Length& b) const { return {meters+b.meters}; } };')
add('Inheritance & composition','وراثت اور کمپوزیشن','9. Inheritance','Inheritance models is-a; composition models has-a.','Public inheritance supports substitution through a base interface. protected members are accessible to derived classes. Prefer composition when you need reuse without a substitutable type relationship.','وراثت بنیادی کلاس کی خصوصیات لیتی ہے۔ کمپوزیشن میں ایک آبجیکٹ دوسرے کو رکھتا ہے۔ صرف کوڈ دوبارہ استعمال کرنے کے لیے وراثت ضروری نہیں۔','Dog d;\nd.eat();\nd.bark();','Add Cat with a meow() operation.','base derived protected overriding hierarchy public private multiple inheritance aggregation composition','', 'class Animal { public: void eat() const { std::cout << "Eating\\n"; } };\nclass Dog : public Animal { public: void bark() const { std::cout << "Woof"; } };')
add('Pointers & addresses','پوائنٹر اور ایڈریس','10. Pointers','A pointer stores an address; dereferencing accesses the pointed-to object.','& obtains an address and * dereferences. Only dereference valid pointers to live objects. Pointer arithmetic is restricted to an array and its one-past position, which cannot be dereferenced.','پوائنٹر میں میموری کا پتہ ہوتا ہے۔ & پتہ اور * اس کی قدر دیتا ہے۔ صرف درست اور زندہ آبجیکٹ کا پوائنٹر استعمال کریں۔','int score{10};\nint* p = &score;\n*p = 20;\nstd::cout << score;','Add 5 to score using only p.','pointer arrays functions strings pointer to pointer linked list parsing horse race UML state')
add('Dynamic memory: new & delete','ڈائنامک میموری','10. Pointers','Dynamic allocation gives objects lifetimes independent of the current scope.','new creates an object; delete destroys it. Match new[] with delete[]. Prefer containers and smart pointers in new code because manual ownership easily causes leaks and invalid accesses.','new آبجیکٹ بناتا اور delete ختم کرتا ہے۔ new[] کے ساتھ delete[] لکھیں۔ جدید کوڈ میں سمارٹ پوائنٹر خود صفائی کرتا ہے۔','int* value = new int{42};\nstd::cout << *value;\ndelete value;\nvalue = nullptr;','Rewrite using make_unique<int>(42).','new delete dynamic allocation heap')
add('Virtual functions & polymorphism','ورچوئل فنکشن','11. Polymorphism','Virtual calls through a base reference or pointer can select derived behavior at runtime.','Pure virtual members make a class abstract. Use override for overrides. Polymorphic deletion through a base pointer requires an appropriate virtual destructor. dynamic_cast can perform checked downcasts in polymorphic hierarchies.','بیس ریفرنس سے ورچوئل فنکشن بلانے پر اصل آبجیکٹ کا فنکشن چلتا ہے۔ pure virtual کلاس abstract ہوتی ہے۔ وراثتی فنکشن پر override لکھیں۔','Circle c;\nconst Shape& s = c;\nstd::cout << s.area();','Add Square implementing area().','late binding abstract pure virtual virtual destructor dynamic_cast typeid RTTI','', 'struct Shape { virtual double area() const=0; virtual ~Shape()=default; };\nstruct Circle : Shape { double area() const override { return 3.14159; } };')
add('Friends, static & this','فرینڈ، سٹیٹک اور this','11. Polymorphism','A friend can access private members; static members belong to the class.','this points to the current object in a non-static member. Static functions have no this pointer. Friendship should be limited because it exposes implementation details. Copy and assignment need consistent ownership semantics.','this موجودہ آبجیکٹ کا پوائنٹر ہے۔ static رکن پوری کلاس سے تعلق رکھتا ہے۔ friend کو private معلومات ملتی ہیں، اس لیے احتیاط سے دیں۔','Box b;\nb.set(9);\nstd::cout << b.get();','Return Box& from set to support chaining.','friend function class static functions this assignment copy constructor','', 'class Box { int value{}; public: void set(int value) { this->value=value; } int get() const { return value; } };')
add('Streams & files','سٹریم اور فائل','12. Streams & files','File streams read and write persistent sequences of bytes.','ofstream writes and ifstream reads. Always check opening and extraction. Binary object serialization needs a defined format; dumping raw objects with pointers is not portable serialization.','ofstream لکھتا اور ifstream پڑھتا ہے۔ فائل کھلنے کی کامیابی چیک کریں۔ پوائنٹر والے آبجیکٹ کی خام میموری محفوظ کرنا درست پورٹیبل فارمیٹ نہیں۔','std::ofstream out("note.txt");\nif (!out) return 1;\nout << "Keep learning!";\nout.close();\nstd::ifstream in("note.txt");\nstd::string line;\nstd::getline(in,line);\nstd::cout << line;','Write and read two lines using a getline loop.','text binary file IO object IO seekg seekp errors stream hierarchy printer output','fstream string')
add('String streams & arguments','متن سٹریم اور آرگومنٹ','12. Streams & files','String streams parse or format text already in memory.','istringstream reads values; ostringstream builds text. Command-line arguments arrive through main(argc, argv). Validate them before converting or using them. Stream insertion/extraction can be overloaded for your types.','سٹرنگ سٹریم میموری میں متن سے قدریں پڑھتا ہے۔ کمانڈ لائن آرگومنٹ argc اور argv سے ملتے ہیں۔ استعمال سے پہلے ان کی جانچ کریں۔','std::istringstream input{"12 30"};\nint a{},b{};\nif (input>>a>>b) std::cout << a+b;','Parse three integers and print their average.','stringstream memory stream command line argc argv overload << >>','sstream')
add('Multifile programs & namespaces','کئی فائلیں اور نیم سپیس','13. Program organization','Separate translation units compile independently and link into one program.','Headers share declarations; source files define implementations. Namespaces group names to avoid collisions. Avoid using namespace std in public headers because it changes every including file’s name lookup.','ہیڈر اعلانات اور سورس فائل تعریف رکھتی ہے۔ فائلیں الگ کمپائل ہو کر لنک ہوتی ہیں۔ نیم سپیس ناموں کا ٹکراؤ روکتا ہے۔','std::cout << math::twice(4);','Move the declaration to math.h and definition to math.cpp in a local project.','header projects inter-file communication namespaces very long number elevator simulation','', 'namespace math { int twice(int n) { return 2*n; } }')
add('Function & class templates','فنکشن اور کلاس ٹیمپلیٹ','14. Templates & exceptions','Templates describe families of functions or classes parameterized by types or values.','Instantiation creates a concrete use. Operations must be valid for the chosen types. Definitions usually belong in headers so they are visible when instantiated.','ٹیمپلیٹ ایک منطق کئی ٹائپس کے لیے استعمال کرتا ہے۔ اندر کے آپریشن منتخب ٹائپ کے لیے درست ہونے چاہییں۔ تعریف عموماً ہیڈر میں ہوتی ہے۔','std::cout << larger(4,7) << "\\n" << larger(2.5,1.2);','Write a smaller function template.','function class templates templated linked list','', 'template<class T> T larger(T a,T b) { return a>b?a:b; }')
add('Exceptions & recovery','ایکسپشن اور بحالی','14. Templates & exceptions','Exceptions transfer control to a matching error handler.','throw signals failure, try marks protected code, catch handles the error. Catch standard exceptions by const reference. Stack unwinding destroys local objects, enabling RAII cleanup.','throw خرابی بتاتا ہے، try کے اندر کوڈ اور catch میں خرابی سنبھالتے ہیں۔ مقامی آبجیکٹ ختم ہوتے وقت وسائل صاف کرتے ہیں۔','try { throw std::runtime_error("Example error"); }\ncatch (const std::exception& e) { std::cout << e.what(); }','Write a divide function that throws on division by zero.','try catch throw multiple exceptions bad_alloc','stdexcept')
add('STL containers','ایس ٹی ایل کنٹینر','15. Standard library','Containers store collections with different access and update trade-offs.','vector is contiguous; list uses linked nodes; deque supports both ends. set stores ordered unique keys and map associates ordered keys with values. Choose by required operations.','vector مسلسل میموری، list جڑے نوڈ اور deque دونوں سروں کی سہولت دیتا ہے۔ set منفرد قدریں اور map کلید کے ساتھ قدر رکھتا ہے۔','std::vector<int> scores{70,85};\nscores.push_back(90);\nfor(int x:scores) std::cout << x << " ";','Store student names and marks in a map.','vector list deque set map containers','vector')
add('Algorithms & iterators','الگورتھم اور اٹیریٹر','15. Standard library','Iterators identify positions; algorithms process ranges of positions.','Most ranges are half-open [begin,end), so end is not an element. sort needs random-access iterators. Functors provide operator() and can supply algorithm predicates.','اٹیریٹر ترتیب میں جگہ بتاتا ہے۔ begin شامل اور end شامل نہیں۔ sort ترتیب لگاتا ہے۔ فنکٹر کو فنکشن کی طرح بلاتے ہیں۔','std::vector<int> v{4,1,3};\nstd::sort(v.begin(),v.end());\nfor(int n:v) std::cout << n << " ";','Use find to locate 3 and check against end().','find count sort merge for_each transform iterators functors function objects','vector algorithm')
add('OO design & UML','سافٹ ویئر ڈیزائن','16. Software development','Design translates requirements into responsibilities and interactions.','Use cases describe an actor’s goals. Class diagrams show types; sequence diagrams show message order; activity diagrams show workflows. Iterate using feedback and tests.','یوز کیس صارف کا مقصد، کلاس ڈایاگرام اقسام اور سیکوئنس ڈایاگرام پیغامات کی ترتیب دکھاتا ہے۔ چھوٹے قدم بنائیں، آزمائیں اور بہتر کریں۔','Task t{"Learn classes",false};\nt.complete=true;\nstd::cout << t.title << ": " << t.complete;','Describe a library borrowing use case and its objects.','waterfall agile use cases actors scenarios class sequence activity diagrams LANDLORD','string','struct Task { std::string title; bool complete; };')
add('auto & decltype','خودکار ٹائپ','Modern language','auto deduces an initializer’s type; decltype obtains an expression’s type.','auto normally drops top-level const and references; auto& preserves reference intent. decltype((x)) can be a reference, unlike decltype(x) for an unparenthesized variable name.','auto قدر سے ٹائپ معلوم کرتا ہے۔ ریفرنس کے لیے auto& لکھیں۔ decltype ایکسپریشن کی ٹائپ حاصل کرتا ہے۔','auto count=4;\ndecltype(count) next=count+1;\nstd::cout << next;','Use auto for a double.','decltype(auto) trailing return -> deduction')
add('nullptr','نل پوائنٹر','Modern language','nullptr is a dedicated null pointer literal.','Its distinct type avoids many ambiguities of integer zero. Test nullable pointers before dereferencing. A null pointer does not refer to a usable object.','nullptr کا مطلب ہے کوئی آبجیکٹ نہیں۔ یہ صفر سے زیادہ واضح ہے۔ اسے dereference نہ کریں۔','int* p=nullptr;\nif(!p) std::cout << "No value yet";','Point p to a live int before printing *p.','NULL null pointer')
add('Range loops & structured bindings','رینج لوپ اور بائنڈنگ','Modern language','Range-for visits elements; structured bindings name a value’s components.','const auto& avoids copies in read-only traversal. C++17 structured bindings can unpack pairs. auto& bindings refer to originals rather than independent copies.','رینج لوپ ہر عنصر تک جاتا ہے۔ بائنڈنگ جوڑے کے حصوں کو نام دیتی ہے۔ اصل عنصر بدلنا ہو تو ریفرنس لیں۔','std::map<std::string,int> marks{{"Ali",80},{"Sara",92}};\nfor(const auto& [name,mark]:marks) std::cout << name << " " << mark << "\\n";','Add another student.','range based for structured bindings unpacking','map string')
add('Brace initialization','بریس سے ابتدا','Modern language','Brace initialization rejects many narrowing conversions.','initializer_list constructors can take precedence. vector<int>{3,7} contains two elements; vector<int>(3,7) contains three copies of 7. int n{3.5} is rejected.','بریس خطرناک narrowing تبدیلی روکتی ہے۔ vector میں بریس عناصر دیتی ہے جبکہ قوسین تعداد اور قدر دے سکتی ہیں۔','std::vector<int> a{3,7}, b(3,7);\nstd::cout << a.size() << " " << b.size();','Predict the sizes before running.','uniform initialization initializer_list narrowing','vector')
add('Lambda expressions','لیمبڈا فنکشن','Modern language','A lambda is a local function object that can capture surrounding values.','[x] captures a copy and [&x] a reference. Captured references must remain valid. mutable permits changing captured copies; generic lambdas use auto parameters.','لیمبڈا چھوٹا مقامی فنکشن ہے۔ [x] کاپی اور [&x] ریفرنس لیتا ہے۔ اصل متغیر ریفرنس کے استعمال تک زندہ ہونا چاہیے۔','int factor{3};\nauto multiply=[factor](int n){ return n*factor; };\nstd::cout << multiply(4);','Write a lambda testing whether a number is even.','capture anonymous generic lambda mutable')
add('enum class','سکوپ والا اینم','Modern language','Scoped enums avoid implicit integer conversion and name collisions.','Qualify values with their type, for example Status::ready. Specify an underlying integral type when required. Explicit conversion is needed for arithmetic.','enum class کی قدر کے ساتھ ٹائپ لکھتے ہیں۔ یہ خود بخود عدد میں نہیں بدلتا۔ اس سے غلط موازنہ کم ہوتا ہے۔','Status s=Status::ready;\nif(s==Status::ready) std::cout << "Ready";','Add a paused value.','scoped enumeration','', 'enum class Status { ready,running,done };')
add('Compile-time programming','کمپائل وقت کا حساب','Modern language','constexpr enables compile-time evaluation when context and inputs permit it.','consteval requires compile-time calls; constinit checks static initialization without making a variable const. static_assert rejects false compile-time conditions.','constexpr حساب کمپائل وقت پر کر سکتا ہے۔ consteval میں یہ ضروری ہے۔ static_assert غلط مستقل شرط پر کمپائل روک دیتا ہے۔','constexpr int n=square(5);\nstatic_assert(n==25);\nstd::cout << n;','Change the assertion to n==24 and inspect the error.','constexpr consteval constinit static_assert','', 'constexpr int square(int n){ return n*n; }')
add('override, final, default & delete','کلاس کے واضح اصول','Modern language','These specifiers express inheritance and special-member intent.','override verifies an override; final prevents further overriding or inheritance. = default asks for generated behavior; = delete prohibits an operation. Delegating constructors call another constructor of the same class.','override تصدیق، final مزید تبدیلی کی ممانعت، default خودکار عمل اور delete استعمال کی پابندی ظاہر کرتا ہے۔','Ticket t;\nstd::cout << "Ticket created";','Try copying t and read the diagnostic.','delegating inheriting constructors override final = default = delete','', 'class Ticket { public: Ticket()=default; Ticket(const Ticket&)=delete; };')
add('noexcept','ایکسپشن نہ نکلنے کا وعدہ','Modern language','noexcept declares that exceptions will not escape a function.','If one escapes, terminate is called. noexcept does not catch exceptions. Non-throwing move operations can help containers move rather than copy.','noexcept سے ایکسپشن باہر نکلے تو پروگرام terminate ہوتا ہے۔ یہ خود catch نہیں کرتا۔','std::cout << twice(4);','Add static_assert(noexcept(twice(4))).','noexcept terminate exception specification','', 'int twice(int n) noexcept { return n*2; }')
add('Move semantics & forwarding','موو اور فارورڈنگ','Modern language','Move operations transfer resources from consumable objects.','std::move is a cast, not a move by itself. Moved-from standard containers remain valid but generally have unspecified state. std::forward preserves a deduced value category.','std::move خود منتقل نہیں کرتا بلکہ موو کے قابل ایکسپریشن بناتا ہے۔ موو کے بعد اصل کنٹینر کی مخصوص قدر فرض نہ کریں۔','std::vector<int> source{1,2,3};\nauto destination=std::move(source);\nstd::cout << destination.size();','Assign new contents to source after moving.','lvalue rvalue && move constructor assignment std::forward perfect forwarding','vector utility')
add('Rule of zero, three & five','زیرو، تھری اور فائیو','Memory & safety','These rules guide copying, moving and destruction for owning classes.','Prefer rule of zero: compose resource-owning members. Manual ownership requires reasoning about destructor, copy constructor and assignment, and modern move constructor and assignment.','string اور vector جیسے ارکان خود وسائل سنبھالتے ہیں۔ دستی وسائل ہوں تو کاپی، موو اور destructor سب کا درست انتظام سوچیں۔','Notes a{{"Learn","Practice"}};\nNotes b=a;\nstd::cout << b.items.size();','Add an item to b and verify a is unchanged.','rule 0 3 5 copy move destructor','vector string','struct Notes { std::vector<std::string> items; };')
add('Variadic templates & folds','متعدد آرگومنٹ ٹیمپلیٹ','Modern language','A parameter pack accepts a variable number of arguments.','C++17 fold expressions apply an operator over a pack. An identity such as zero for addition allows an empty pack when appropriate.','پیرامیٹر پیک کئی آرگومنٹ لیتا ہے۔ فولڈ ان سب پر آپریٹر لگاتا ہے۔ جمع میں صفر ابتدائی قدر ہے۔','std::cout << sum(1,2,3,4);','Call sum() with no arguments.','variadic parameter pack fold expressions','', 'template<class... T> auto sum(T... x){ return (0 + ... + x); }')
add('Advanced templates','جدید ٹیمپلیٹ','Modern language','Specialization and compile-time selection customize generic code.','if constexpr discards unselected branches during instantiation. SFINAE removes unsuitable candidates during substitution. Alias templates name type expressions; typename identifies dependent types where required.','if constexpr غیر منتخب شاخ ہٹا دیتا ہے۔ specialization خاص ٹائپ کے لیے الگ عمل دیتا ہے۔ alias ٹائپ کا آسان نام ہے۔','show(7);\nshow(2.5);','Add a branch for bool.','specialization full partial SFINAE alias using typename class if constexpr','type_traits','template<class T> void show(T x){\n    if constexpr(std::is_integral_v<T>) std::cout << "Integer: ";\n    else std::cout << "Other: ";\n    std::cout << x << "\\n";\n}')
add('Concepts & requires','کانسیپٹ اور شرط','Modern language','Concepts name compile-time requirements on template arguments.','C++20 constraints reject types that do not satisfy required properties. They improve diagnostics and influence overload selection. requires expressions check whether operations are well formed.','کانسیپٹ ٹائپ پر شرط لگاتا ہے۔ شرط پوری نہ ہو تو کمپائل خرابی آتی ہے۔ requires مطلوبہ آپریشن چیک کرتا ہے۔','std::cout << twice(6);','Try twice(2.5) and explain why it fails.','concept requires constraint C++20','concepts','template<std::integral T> T twice(T n){ return n+n; }')
add('Ranges & views','رینج اور ویوز','Modern language','Views provide lightweight, often lazy adaptations of sequences.','C++20 pipelines compose filters and transformations. Lazy work happens during traversal. Views often borrow the source, so ensure the source outlives use of the view.','ویوز ڈیٹا فلٹر یا تبدیل کرتی ہیں۔ حساب اکثر پڑھتے وقت ہوتا ہے۔ اصل ڈیٹا ویو کے استعمال تک زندہ ہونا چاہیے۔','std::vector<int> v{1,2,3,4,5,6};\nauto evens=v|std::views::filter([](int n){return n%2==0;});\nfor(int n:evens) std::cout << n << " ";','Chain a transform to double the even values.','ranges views pipeline filter transform C++20','ranges vector')
add('Modules & coroutines','ماڈیول اور کوروٹین','Modern language','Modules organize exported interfaces; coroutines suspend and resume functions.','C++20 modules use export module and import and require appropriate build setup. Coroutines use co_await, co_yield or co_return with a promise type. This example demonstrates deferred execution; full module builds belong in a configured local project.','ماڈیول export اور import سے انٹرفیس بانٹتے ہیں۔ کوروٹین رک کر دوبارہ چل سکتی ہے اور promise_type چاہتی ہے۔ ماڈیول کے لیے مناسب مقامی بلڈ درکار ہے۔','auto t=greet();\nt.h.resume();','Explain why the message appears only after resume().','modules import export coroutines co_await co_yield co_return','coroutine','struct Task {\n    struct promise_type {\n        Task get_return_object(){ return {std::coroutine_handle<promise_type>::from_promise(*this)}; }\n        std::suspend_always initial_suspend() noexcept { return {}; }\n        std::suspend_always final_suspend() noexcept { return {}; }\n        void return_void(){}\n        void unhandled_exception(){ std::terminate(); }\n    };\n    std::coroutine_handle<promise_type> h;\n    Task(std::coroutine_handle<promise_type> x):h(x){}\n    Task(const Task&)=delete;\n    ~Task(){ if(h) h.destroy(); }\n};\nTask greet(){ std::cout << "Resumed!"; co_return; }')
add('Three-way comparison <=>','تین طرفہ موازنہ','Modern language','The spaceship operator represents less, equal or greater in one comparison.','A defaulted C++20 spaceship compares members in declaration order. Relational operators can be rewritten from it. Defaulting can also implicitly declare equality.','اس آپریٹر سے کم، برابر یا زیادہ کا نتیجہ ملتا ہے۔ default ارکان کا ترتیب سے موازنہ کرتا ہے۔','Point a{1,2},b{1,3};\nstd::cout << (a<b);','Compare equal points with ==.','spaceship <=> ordering C++20','compare','struct Point { int x,y; auto operator<=>(const Point&) const=default; };')
add('Attributes','کمپائلر کے اشارے','Modern language','Attributes attach standardized information to code.','nodiscard encourages result checking, maybe_unused suppresses appropriate warnings, deprecated marks discouraged APIs and fallthrough documents intentional switch behavior. Diagnostics depend on the compiler.','nodiscard نتیجہ نظرانداز کرنے پر تنبیہ دے سکتا ہے۔ deprecated پرانا انٹرفیس اور fallthrough جان بوجھ کر اگلے case میں جانا دکھاتا ہے۔','std::cout << answer();','Ignore answer() and inspect compiler warnings.','nodiscard maybe_unused deprecated fallthrough','', '[[nodiscard]] int answer(){ return 42; }')
add('RAII & resource lifetime','وسائل اور آبجیکٹ کی زندگی','Memory & safety','RAII binds resource ownership to object lifetime.','Acquire during initialization and release during destruction. Normal returns and exception unwinding then share cleanup. Resources include memory, files and locks.','آبجیکٹ وسائل لیتا اور ختم ہوتے وقت چھوڑ دیتا ہے۔ ایکسپشن میں بھی یہی صفائی ہوتی ہے۔','{\n    auto n=std::make_unique<int>(42);\n    std::cout << *n;\n} // automatic cleanup','Explain exactly when memory is released.','RAII resource acquisition initialization cleanup scope','memory')
add('Smart pointers','سمارٹ پوائنٹر','Memory & safety','Smart pointers express ownership and automatically release managed objects.','unique_ptr owns exclusively; shared_ptr shares ownership; weak_ptr observes without increasing the strong count and can break cycles. Prefer make_unique and make_shared.','unique_ptr ایک مالک، shared_ptr مشترک مالک اور weak_ptr بغیر ملکیت کے مشاہدہ دیتا ہے۔ صفائی خودکار ہوتی ہے۔','auto score=std::make_unique<int>(95);\nstd::cout << *score;','Move score into another unique_ptr.','unique_ptr shared_ptr weak_ptr make_unique make_shared','memory')
add('Memory bugs','میموری کی خرابیاں','Memory & safety','Leaks, invalid lifetime accesses and out-of-bounds operations are common memory bugs.','A dangling pointer outlives its object. Use-after-free and double deletion are undefined behavior. Prefer ownership types and checked access where useful.','ختم آبجیکٹ کا پوائنٹر dangling ہے۔ آزاد میموری استعمال کرنا اور حد سے باہر جانا غلط ہے۔ ملکیت واضح رکھیں۔','std::vector<int> v{10,20};\ntry { std::cout << v.at(5); }\ncatch(const std::out_of_range&){ std::cout << "Index outside vector"; }','Change the index to 1.','memory leak dangling use after free double free buffer overflow','vector stdexcept')
add('Object slicing','آبجیکٹ سلائسنگ','Memory & safety','Slicing loses the derived portion when copying into a base object by value.','Use references or pointers to preserve dynamic dispatch. Copying polymorphic objects by value requires an explicit design such as a virtual clone operation.','بیس قدر میں کاپی سے اضافی حصہ کٹ جاتا ہے۔ ریفرنس یا پوائنٹر اصل قسم برقرار رکھتا ہے۔','Child c;\nBase sliced=c;\nconst Base& kept=c;\nstd::cout << sliced.name() << " " << kept.name();','Change sliced into a reference.','object slicing','', 'struct Base { virtual const char* name() const{return "Base";} virtual ~Base()=default; };\nstruct Child:Base { const char* name() const override{return "Child";} };')
add('vtable & vptr','ورچوئل جدول','Memory & safety','Many compilers implement dynamic dispatch using a virtual table and hidden pointer.','These are common implementation techniques, not standard-mandated layouts. A virtual call selects the final overrider. Do not assume a vptr location or portable object memory representation.','اکثر کمپائلر پوشیدہ پوائنٹر اور جدول استعمال کرتے ہیں۔ معیار ان کی خاص ترتیب لازمی نہیں کرتا۔','Child c;\nBase& b=c;\nb.say();','Explain why Child::say executes.','vtable vptr internals','', 'struct Base {virtual void say(){std::cout<<"Base";} virtual ~Base()=default;};\nstruct Child:Base {void say() override{std::cout<<"Child";}};')
add('Diamond & virtual inheritance','ڈائمنڈ وراثت','Memory & safety','Virtual inheritance shares a common base subobject across inheritance paths.','Without it a diamond may contain two common-base copies. The most-derived constructor initializes virtual bases. Exact layout is implementation-dependent.','virtual inheritance مشترک بیس کی ایک کاپی رکھتی ہے۔ سب سے آخری ڈیرائیوڈ کلاس اس کی ابتدا کرتی ہے۔','Final f;\nf.value=7;\nstd::cout << f.value;','Remove virtual and inspect ambiguous access.','diamond virtual base multiple inheritance layout','', 'struct Root{int value{};};\nstruct Left:virtual Root{};\nstruct Right:virtual Root{};\nstruct Final:Left,Right{};')
add('Alignment & padding','میموری الائنمنٹ','Memory & safety','Alignment restricts addresses; padding helps meet those requirements.','sizeof includes padding and can exceed member-size totals. alignof reports requirements and alignas requests alignment. Platform differences make raw struct dumps unsuitable as portable file formats.','sizeof میں padding شامل ہے۔ alignof ترتیب بتاتا ہے۔ مختلف پلیٹ فارم پر سائز بدل سکتا ہے۔','std::cout << sizeof(Record) << " " << alignof(Record);','Reorder members and compare sizes.','sizeof alignas alignof padding','', 'struct Record{char label; int value;};')
add('Bit fields & bitset','بٹس اور بٹ سیٹ','Memory & safety','Bit-oriented types represent flags and fixed sets of bits.','bitset provides set, reset and test. Class bit fields restrict widths but their allocation and layout are implementation-dependent. Define explicit encoding for wire formats.','bitset میں مقررہ بٹس ہوتے ہیں۔ set بٹ روشن اور reset بند کرتا ہے۔ bit fields کی ترتیب ہر کمپائلر پر ایک جیسی نہیں۔','std::bitset<8> flags;\nflags.set(2);\nstd::cout << flags << " " << flags.test(2);','Set bit 0 and print count().','bit fields bitset masks','bitset')
add('Sanitizers & undefined behavior','سینیٹائزر اور غیر معین رویہ','Memory & safety','Undefined behavior means the language imposes no outcome requirements.','AddressSanitizer detects many memory errors; UBSan catches selected undefined operations. Locally use -g -fsanitize=address,undefined. A clean run does not prove every path safe.','غیر معین رویے میں نتیجے کی ضمانت نہیں۔ سینیٹائزر کئی غلطیاں پکڑتے ہیں مگر تمام غلطیوں کی عدم موجودگی ثابت نہیں کرتے۔','std::vector<int> v{1,2,3};\nfor(std::size_t i=0;i<v.size();++i) std::cout << v[i];','Compile locally with sanitizers and exercise boundaries.','ASan UBSan AddressSanitizer UB Valgrind','vector')
add('Modern containers & span','جدید کنٹینر','Modern library','Modern containers and adapters provide fixed storage, hashing and specialized access.','array owns fixed-size storage. unordered_map/set use hashing. stack, queue and priority_queue adapt containers. span is a non-owning contiguous view and must not outlive its data.','array مقررہ ذخیرہ اور unordered_map ہیش تلاش دیتا ہے۔ span ڈیٹا کا مالک نہیں، اصل ڈیٹا زندہ رہنا ضروری ہے۔','std::array<int,3> data{4,5,6};\nstd::span<int> view{data};\nview[0]=9;\nstd::cout << data[0];','Use unordered_map to count words.','array unordered_map unordered_set priority_queue stack queue span','array span')
add('Utility types','مددگار ٹائپس','Modern library','Utilities model grouped values, optional results, alternatives and borrowed text.','pair and tuple group values; optional models absence; variant stores one of known types; any erases a stored type. string_view borrows text without extending its lifetime.','optional قدر کی موجودگی بتاتا ہے۔ variant کئی ٹائپس میں سے ایک رکھتا ہے۔ string_view متن کا مالک نہیں ہوتا۔','std::optional<int> score;\nstd::cout << score.value_or(0) << "\\n";\nscore=95;\nstd::cout << *score;','Store an int or string in a variant and visit it.','pair tuple optional variant any string_view','optional')
add('Functional tools','فنکشن کے اوزار','Modern library','Callable utilities store, adapt and invoke operations.','function type-erases a copyable callable with a matching signature. invoke calls several callable forms uniformly. Lambdas are often clearer than bind for adapting arguments.','std::function فنکشن یا لیمبڈا رکھتا ہے۔ invoke مختلف callable چیزیں چلاتا ہے۔ چھوٹی تبدیلی کے لیے لیمبڈا واضح ہے۔','std::function<int(int)> twice=[](int n){return 2*n;};\nstd::cout << std::invoke(twice,5);','Assign a tripling lambda.','std::function bind invoke','functional')
add('Modern algorithms','جدید الگورتھم','Modern library','Algorithms express common sequence operations without manual loop bookkeeping.','all_of, any_of and none_of test predicates; accumulate folds values; iota fills increasing values. Parallel execution policies require care with shared mutation.','all_of سب عناصر کی شرط دیکھتا ہے۔ accumulate جمع کرتا ہے۔ متوازی کام میں مشترک تبدیلی محفوظ رکھیں۔','std::vector<int> v(5);\nstd::iota(v.begin(),v.end(),1);\nstd::cout << std::accumulate(v.begin(),v.end(),0);','Check all values are positive with all_of.','all_of any_of none_of accumulate iota parallel execution policy','vector numeric algorithm')
add('Time, randomness & regex','وقت، رینڈم اور پیٹرن','Modern library','chrono models time, random supplies engines and distributions, regex matches patterns.','Use steady_clock for durations. Seed an engine once and use a distribution for the range. For simple patterns, ordinary string operations may be clearer than regex.','chrono وقت سنبھالتا ہے۔ random میں انجن اور تقسیم الگ ہیں۔ regex متن کے پیٹرن دیکھتا ہے۔','std::mt19937 engine{42};\nstd::uniform_int_distribution<int> dice(1,6);\nstd::cout << dice(engine);','Generate five rolls with the same engine.','chrono random regex duration steady_clock','random')
add('Filesystem & formatting','فائل سسٹم اور فارمیٹنگ','Modern library','filesystem models paths and operations; format creates type-aware formatted strings.','filesystem is C++17 and format is C++20, with library support varying by compiler. Prefer path operations over manual slash handling. Check permission and missing-file errors.','filesystem راستے اور فولڈر سنبھالتا ہے۔ format متن میں قدریں رکھتا ہے۔ فائل کی اجازت اور موجودگی چیک کریں۔','std::filesystem::path p{"lessons"};\np/="intro.cpp";\nstd::cout << p.generic_string();','Print filename() and extension().','filesystem std::format paths directories','filesystem')
add('Custom hashing','اپنا ہیش','Modern library','Hash functions map keys to size_t values for hash-based lookup.','Equal keys must have equal hashes. Collisions are allowed and resolved through equality. A stored key’s identity must remain stable.','برابر کلیدوں کا ہیش برابر ہونا ضروری ہے۔ مختلف کلیدوں کا ایک ہیش ہو سکتا ہے۔ کنٹینر برابری سے فرق دیکھتا ہے۔','std::unordered_map<Key,int,Hash> marks;\nmarks[Key{7}]=90;\nstd::cout << marks.at(Key{7});','Add a second key.','custom hash equality unordered','unordered_map functional','struct Key {int id; bool operator==(const Key&) const=default;};\nstruct Hash {std::size_t operator()(Key k) const{return std::hash<int>{}(k.id);}};')
add('Modern error handling','جدید خرابی کا انتظام','Modern library','Explicit result types can represent success or failure without exceptions.','expected in C++23 stores a value or error. error_code supports non-throwing interfaces. Basic exception safety preserves invariants; strong preserves prior state; no-throw prevents escaping exceptions.','expected نتیجہ یا خرابی رکھتا ہے۔ strong guarantee میں ناکامی پر پرانی حالت برقرار رہتی ہے۔ پہلے کامیابی چیک کریں۔','auto r=divide(10,0);\nif(r) std::cout << *r;\nelse std::cout << r.error();','Call divide(10,2).','expected error_code basic strong nothrow exception guarantee','expected string','std::expected<int,std::string> divide(int a,int b){ if(b==0) return std::unexpected("Cannot divide by zero"); return a/b; }')
add('Threads & jthread','تھریڈ','Concurrency','A thread is an independent execution sequence in a process.','thread requires join or detach before destruction. C++20 jthread automatically joins and supports cooperative cancellation. Shared mutable data still needs synchronization.','تھریڈ الگ عمل ہے۔ thread کو join یا detach کرنا ضروری ہے۔ jthread خود join کرتا ہے۔ مشترک ڈیٹا محفوظ رکھیں۔','std::jthread worker([]{std::cout << "Hello from a worker";});','Create a second worker without shared mutable state.','thread jthread join detach stop_token','thread')
add('Mutexes & locks','میوٹیکس اور لاک','Concurrency','Mutexes grant exclusive access to protected critical sections.','lock_guard and scoped_lock unlock on scope exit. unique_lock supports flexible ownership and condition-variable waiting. All conflicting access must follow the same protection discipline.','میوٹیکس ایک وقت میں ایک تھریڈ کو اجازت دیتا ہے۔ lock_guard خود لاک چھوڑتا ہے۔ ہر مشترک رسائی ایک ہی اصول سے محفوظ کریں۔','std::mutex mutex;\nint count{};\nauto work=[&]{for(int i=0;i<1000;++i){std::lock_guard lock(mutex);++count;}};\nstd::jthread a(work),b(work);\na.join(); b.join();\nstd::cout << count;','Explain why both workers use the same mutex.','mutex lock_guard unique_lock scoped_lock','thread mutex')
add('Synchronization','تھریڈ ہم آہنگی','Concurrency','Synchronization coordinates when concurrent work can proceed.','condition_variable waits with a mutex and predicate to handle spurious wakeups. Semaphores count permits; latches count down once; barriers support repeated phases. Timing alone is not synchronization.','condition_variable کے ساتھ شرط چیک کریں۔ semaphore اجازتیں، latch ایک مرحلہ اور barrier کئی مرحلے سنبھالتا ہے۔','std::latch ready{1};\nstd::jthread worker([&]{std::cout << "Prepared\\n";ready.count_down();});\nready.wait();\nstd::cout << "Continue";','Explain the guaranteed message order.','condition_variable semaphore latch barrier','thread latch')
add('Atomics & memory ordering','ایٹامک اور میموری ترتیب','Concurrency','Atomic operations prevent data races on the atomic object itself.','fetch_add is an indivisible read-modify-write. Sequential consistency is the default. relaxed provides atomicity but does not publish unrelated data.','ایٹامک عمل درمیان میں نہیں ٹوٹتا۔ relaxed دوسری معلومات کی ترتیب کی ضمانت نہیں دیتا۔','std::atomic<int> count{0};\nstd::jthread a([&]{for(int i=0;i<1000;++i) ++count;});\na.join();\nstd::cout << count.load();','Add another incrementing worker and join it.','atomic memory ordering relaxed acquire release seq_cst','atomic thread')
add('Async, futures & promises','ایسنک اور فیوچر','Concurrency','A future represents a result that may become ready later.','async with launch::async requests asynchronous execution. get waits and propagates stored exceptions. promise supplies results manually; packaged_task connects a callable and future.','future بعد میں آنے والا نتیجہ ہے۔ get انتظار کر کے نتیجہ یا ایکسپشن دیتا ہے۔ promise خود نتیجہ فراہم کرتا ہے۔','auto r=std::async(std::launch::async,[]{return 6*7;});\nstd::cout << r.get();','Return a string from the task.','async future promise packaged_task','future')
add('Concurrency bugs','متوازی کوڈ کی غلطیاں','Concurrency','Concurrency bugs violate required ordering or ownership across executions.','Unsynchronized conflicting ordinary-memory accesses form a data race and undefined behavior. Deadlock is cyclic waiting. scoped_lock avoids deadlock while acquiring multiple mutexes, but overall logic still needs design.','data race غیر محفوظ مشترک رسائی ہے۔ deadlock میں تھریڈ ایک دوسرے کا انتظار کرتے رہتے ہیں۔ لاک کی ترتیب اور ملکیت واضح رکھیں۔','std::mutex a,b;\n{std::scoped_lock lock(a,b); std::cout << "Both locks held";}','Describe opposite lock ordering in two threads.','race condition deadlock data race thread safe','mutex')
add('SOLID & dependency injection','سولیڈ اور ڈیپنڈنسی انجیکشن','Design & tools','SOLID guides focused responsibilities and flexible dependencies.','Keep cohesive responsibilities, stable interfaces, substitutability and narrow APIs. Depend on abstractions. Injection supplies dependencies from outside, simplifying substitution and tests.','ہر کلاس کی ذمہ داری واضح رکھیں۔ dependency injection میں مطلوبہ چیز باہر سے دی جاتی ہے، اس لیے جانچ آسان ہوتی ہے۔','ConsoleLog log;\nService service{log};\nservice.run();','Provide a different logger.','SOLID single responsibility open closed Liskov interface segregation dependency inversion injection','', 'struct Log {virtual void write()=0;virtual ~Log()=default;};\nstruct ConsoleLog:Log {void write() override{std::cout<<"Working";}};\nstruct Service {Log& log; void run(){log.write();}};')
add('Design patterns','ڈیزائن پیٹرن','Design & tools','Patterns name reusable approaches to recurring design problems.','Strategy swaps behavior, Factory creates objects, Observer notifies, Builder assembles and Decorator wraps behavior. Singleton has global-state and testability trade-offs. Use a pattern to solve an actual problem.','Strategy عمل بدلتا، Factory آبجیکٹ بناتا اور Observer اطلاع دیتا ہے۔ صرف حقیقی ضرورت پر پیٹرن لگائیں۔','auto add=[](int a,int b){return a+b;};\nstd::cout << calculate(3,4,add);','Pass a multiplication strategy.','Singleton Factory Observer Strategy Builder Decorator','functional','int calculate(int a,int b,const std::function<int(int,int)>& strategy){return strategy(a,b);}')
add('CRTP, PIMPL & type erasure','سی پلس پلس محاورے','Design & tools','Idioms achieve recurring abstraction goals using language mechanisms.','CRTP passes the derived type to a base template for static polymorphism. PIMPL hides implementation behind a pointer. Type erasure exposes a uniform interface over hidden concrete types.','CRTP static polymorphism دیتا ہے۔ PIMPL تفصیل پوائنٹر کے پیچھے اور type erasure اصل ٹائپ ایک انٹرفیس کے پیچھے چھپاتا ہے۔','Printer p;\np.run();','Add another derived printing type.','CRTP PIMPL type erasure idioms','', 'template<class D> struct Printable {void run(){static_cast<D*>(this)->print();}};\nstruct Printer:Printable<Printer>{void print(){std::cout<<"Static dispatch";}};')
add('Headers, ODR & linking','ہیڈر اور لنکنگ','Design & tools','The one-definition rule constrains definitions across translation units.','Include guards prevent repeated inclusion per translation unit. pragma once is widespread but non-standard. extern declares external definitions; namespace-scope static gives internal linkage. C++17 inline variables support suitable header definitions.','انکلوڈ گارڈ بار بار تعریف روکتا ہے۔ extern باہر کی تعریف اور namespace کا static اندرونی linkage دیتا ہے۔ inline متغیر ہیڈر میں تعریف آسان کرتا ہے۔','std::cout << config::limit;','Put the inline variable in a guarded header used by two files.','include guards pragma once forward declarations ODR inline variables static extern linkage','', 'namespace config {inline constexpr int limit=100;}')
add('Build tools: GCC, Clang & CMake','بلڈ کے اوزار','Design & tools','Build tools coordinate compilation and linking.','For a small local program use g++ -std=c++23 -Wall -Wextra main.cpp -o app. CMake declares targets and dependencies and generates a build system; Make executes dependency rules.','بلڈ ٹول سورس کمپائل اور لنک کرتا ہے۔ CMake ٹارگٹ اور تعلقات بتاتا ہے۔ ورژن اور وارننگ آپشن واضح رکھیں۔','std::cout << "Build successful";','Save as main.cpp and compile with the command above.','g++ clang++ Makefile CMake compiler linker')
add('Debugging with GDB & LLDB','ڈی بگنگ','Design & tools','Debuggers pause execution to inspect program state.','Build locally with -g. Set breakpoints, step statements, inspect variables and read backtraces. Start with a minimal reproducer. Logging may affect concurrent timing.','ڈی بگر پروگرام روک کر حالت دکھاتا ہے۔ breakpoint لگائیں اور ایک ایک قدم چلائیں۔ پہلے چھوٹی مثال میں غلطی دہرائیں۔','int total{};\nfor(int i=1;i<=3;++i) total+=i;\nstd::cout << total;','Inspect total and i at each iteration in a local debugger.','gdb lldb core dumps logging breakpoints')
add('Unit testing','یونٹ ٹیسٹنگ','Design & tools','A unit test checks a focused behavior against an expected outcome.','Test ordinary, boundary and failure inputs. Google Test and Catch2 provide assertions and runners. assert may be disabled by NDEBUG and must not replace input validation.','عام، حد والی اور غلط ان پٹ آزمائیں۔ assert ریلیز میں بند ہو سکتا ہے، اس لیے اصل ان پٹ جانچ الگ رکھیں۔','assert(add(2,3)==5);\nassert(add(0,0)==0);\nstd::cout << "Checks passed";','Add a negative-number test.','Google Test Catch2 unit testing','cassert','int add(int a,int b){return a+b;}')
add('Coding standards & analysis','کوڈ کا معیار','Design & tools','Standards make code easier to read and maintain.','Core Guidelines emphasize clear ownership and interfaces. clang-format standardizes layout; clang-tidy checks selected bug patterns and modernization. Review automated suggestions.','واضح نام اور ملکیت کوڈ آسان بناتے ہیں۔ clang-format شکل اور clang-tidy ممکنہ غلطیاں دیکھتا ہے۔ مشورے سوچ کر اپنائیں۔','const int lessonsPerWeek{5};\nstd::cout << lessonsPerWeek;','Run formatting and review a clang-tidy warning locally.','Core Guidelines clang-format clang-tidy coding standards lint')
add('Performance & Big-O','کارکردگی اور بگ او','Design & tools','Complexity describes scaling; profiling measures actual behavior.','Linear search is O(n); binary search on sorted random-access data uses O(log n) comparisons. Cache locality, allocations and constants matter. Measure representative workloads before optimizing.','بگ او کام کے بڑھنے کو بتاتا ہے۔ اصل رفتار پر کیش اور میموری بھی اثر رکھتے ہیں۔ اندازے کے بجائے پروفائل کریں۔','std::vector<int> v{1,3,5,7,9};\nstd::cout << std::binary_search(v.begin(),v.end(),7);','Compare linear and binary search locally on a large sorted vector.','Big-O cache locality profiling perf gprof complexity','vector algorithm')
